def rectangles_overlap(r1, r2):
    # Check if the rectangles do not overlap on the x-axis
    if r1[2] <= r2[0] or r2[2] <= r1[0]:
        return False
    # Check if the rectangles do not overlap on the y-axis
    if r1[3] <= r2[1] or r2[3] <= r1[1]:
        return False
    return True
