import math

def classify_triangle_by_sides(p1, p2, p3):
    # Function to calculate the distance between two points
    def distance(a, b):
        return math.hypot(a[0] - b[0], a[1] - b[1])

    # Calculate the three side lengths
    d1 = distance(p1, p2)
    d2 = distance(p2, p3)
    d3 = distance(p3, p1)

    # Classify the triangle based on side lengths
    if d1 == d2 == d3:
        return 'equilateral'
    elif d1 == d2 or d2 == d3 or d3 == d1:
        return 'isosceles'
    else:
        return 'scalene'
