def is_point_on_segment(p, a, b):
    # Check if p lies on the line segment from a to b
    # First, check if the cross product is zero (collinear)
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p lies on the line defined by a and b
    if cross(a, b, p) != 0:
        return False

    # Check if p lies between a and b (inclusive)
    def dot(o, a, b):
        return (a[0] - o[0]) * (b[0] - o[0]) + (a[1] - o[1]) * (b[1] - o[1])

    if dot(a, p, b) < 0:
        return False

    # Check if p is within the bounds of the segment
    if (p[0] < min(a[0], b[0]) or p[0] > max(a[0], b[0]) or
        p[1] < min(a[1], b[1]) or p[1] > max(a[1], b[1])):
        return False

    return True
```

