def is_point_on_segment(p, a, b):
    # Check if p lies on the line defined by a and b
    # and also lies between a and b
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Check if p is colinear with a and b
    if cross_product(a, b, p) != 0:
        return False

    # Check if p is between a and b
    def is_between(a, b, p):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    return is_between(a, b, p)
