def is_convex_polygon(points):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check all consecutive triplets of points
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        # If the cross product changes sign, the polygon is not convex
        if cross(a, b, c) < 0:
            return False
        if cross(a, b, c) == 0:
            return False  # Collinear points mean not convex
    return True
```

