def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False

    def cross(p, q, r):
        # Compute the cross product of vectors (q-p) and (r-p)
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    # Check all consecutive triplets of points
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        c = cross(p, q, r)
        if c == 0:
            return False  # Collinear points
        if (c < 0) != (cross(p, q, r) < 0):
            return False  # Change in turning direction

    return True
```

