        return (q[0] - p[0]) * (r[1] - q[1]) - (q[1] - p[1]) * (r[0] - q[0])

    prev = None
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        curr = cross(p, q, r)
        if curr == 0:
            return False  # Collinear points make it non-convex
        if prev is not None and (prev > 0) != (curr > 0):
            return False  # Change in direction
        prev = curr
    return True
