def is_square(p1, p2, p3, p4):
    def dist_sq(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    points = [p1, p2, p3, p4]
    distances = []
    for i in range(4):
        distances.append(dist_sq(points[i], points[(i + 1) % 4]))
        distances.append(dist_sq(points[i], points[(i + 2) % 4]))

    # There should be exactly 2 distinct distances: 4 equal sides and 2 equal diagonals
    return sorted(distances) == [d] * 4 + [d * 2] * 2 for d in set(distances)
