from copy import deepcopy

def flood_fill(grid, sr, sc, new_value):
    original_value = grid[sr][sc]
    if original_value == new_value:
        return deepcopy(grid)

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or visited[r][c] or grid[r][c] != original_value:
            return
        visited[r][c] = True
        grid[r][c] = new_value
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    dfs(sr, sc)
    return deepcopy(grid)
```

