def border_sum(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    if rows == 1 or cols == 1:
        return sum(sum(row) for row in grid)
    total = 0
    for i in range(rows):
        total += grid[i][0]
        total += grid[i][cols - 1]
    for j in range(1, cols - 1):
        total += grid[0][j]
        total += grid[rows - 1][j]
    return total
```

