def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True
    rows = len(grid)
    cols = len(grid[0])
    for i in range(rows):
        for j in range(cols):
            current = grid[i][j]
            # Check neighbors
            if i > 0 and grid[i-1][j] == current:
                return False
            if j > 0 and grid[i][j-1] == current:
                return False
            # Check if the value is consistent with the checkerboard pattern
            expected = (i + j) % 2
            if current != (expected):
                return False
    return True
