def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is valid

    rows, cols = len(grid), len(grid[0])
    expected = grid[0][0]

    for i in range(rows):
        for j in range(cols):
            # Calculate expected value based on (i + j) parity
            if (i + j) % 2 == 0:
                expected_val = grid[0][0]
            else:
                expected_val = grid[0][1]

            if grid[i][j] != expected_val:
                return False

            # Check adjacent cells (right and down)
            if i < rows - 1 and grid[i][j] == grid[i+1][j]:
                return False
            if j < cols - 1 and grid[i][j] == grid[i][j+1]:
                return False

    return True
```

