def parse_simple_expr(s):
    # Find the operator position
    for i, char in enumerate(s):
        if char in "+-*/":
            operator_pos = i
            break
    # Split the string into operands
    left = int(s[:operator_pos])
    right = int(s[operator_pos+1:])
    operator = s[operator_pos]
    # Perform the operation
    if operator == '+':
        return left + right
    elif operator == '-':
        return left - right
    elif operator == '*':
        return left * right
    elif operator == '/':
        return left / right
```

