def game_score_tally(events):
    score = 0
    for event in events:
        if event[0] == "score":
            score += event[1]
        elif event[0] == "bonus":
            score *= 2
        elif event[0] == "penalty":
            score -= event[1]
        # Ensure score does not go below 0
        score = max(score, 0)
    return score
