    mode = "IDLE"
    for op, value in events:
        if op == "set_target":
            target = value
        elif op == "read":
            current_temp = value
            if current_temp < target:
                mode = "HEAT"
            elif current_temp > target:
                mode = "COOL"
            else:
                mode = "IDLE"
    return mode
```

