def traffic_light_log(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    total_cycle = red_ticks + green_ticks + yellow_ticks
    log = []
    for i in range(n_ticks):
        cycle_index = i % total_cycle
        if cycle_index < red_ticks:
            log.append("RED")
        elif cycle_index < red_ticks + green_ticks:
            log.append("GREEN")
        elif cycle_index < red_ticks + green_ticks + yellow_ticks:
            log.append("YELLOW")
    return log
