def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)
    # Set to track cleaned cells
    cleaned = set()
    # Initial position and direction
    x, y = 0, 0
    direction = "N"
    cleaned.add((x, y))

    # Directions: North, East, South, West
    directions = ["N", "E", "S", "W"]

    for cmd in commands:
        if cmd == "L":
            # Turn counter-clockwise (left)
            direction = directions[(directions.index(direction) - 1) % 4]
        elif cmd == "R":
            # Turn clockwise (right)
            direction = directions[(directions.index(direction) + 1) % 4]
        elif cmd == "F":
            # Move forward
            if direction == "N":
                new_x, new_y = x, y + 1
            elif direction == "E":
                new_x, new_y = x + 1, y
            elif direction == "S":
                new_x, new_y = x, y - 1
            elif direction == "W":
                new_x, new_y = x - 1, y

            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add current position to cleaned cells
            cleaned.add((x, y))

    return len(cleaned)
