def coffee_machine_credit(events, prices, stock):
    credit = 0
    total_dispensed = 0
    # Create a copy of the stock dictionary to avoid modifying the input
    final_stock = dict(stock)

    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select":
            drink = value
            if drink in prices and drink in final_stock and final_stock[drink] > 0 and credit >= prices[drink]:
                credit -= prices[drink]
                final_stock[drink] -= 1
                total_dispensed += 1
            # If conditions not met, do nothing

    return (credit, final_stock, total_dispensed)
