def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def get_light_state(t, durations):
        red_ticks, green_ticks, yellow_ticks = durations
        cycle_length = red_ticks + green_ticks + yellow_ticks
        t_in_cycle = t % cycle_length
        if t_in_cycle < red_ticks:
            return 'RED'
        elif t_in_cycle < red_ticks + green_ticks:
            return 'GREEN'
        else:
            return 'YELLOW'

    count = 0
    for t in range(n_ticks):
        state_a = get_light_state(t, durations_a)
        state_b = get_light_state(t, durations_b)
        if state_a == 'GREEN' and state_b == 'GREEN':
            count += 1
    return count
```

