def is_convex_polygon(points):
    def cross(p, q, r):
        # Returns the cross product of vectors p->q and p->r
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    n = len(points)
    if n < 3:
        return False  # A polygon must have at least 3 vertices

    # Check all consecutive triplets of points
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        # Calculate cross product to determine turn direction
        c = cross(p, q, r)
        # If the cross product changes sign, the polygon is not convex
        if c < 0:
            return False
        elif c == 0:
            # If three points are collinear, it's not a convex polygon
            if cross(points[i - 1], p, q) == 0 and cross(q, r, points[(i + 3) % n]) == 0:
                return False

    return True
```

