import math

def is_square(p1, p2, p3, p4):
    def distance(p, q):
        return math.hypot(p[0]-q[0], p[1]-q[1])

    def is_perpendicular(v1, v2):
        return v1[0]*v2[0] + v1[1]*v2[1] == 0

    points = [p1, p2, p3, p4]
    sides = []
    for i in range(4):
        v = (points[i+1][0] - points[i][0], points[i+1][1] - points[i][1])
        sides.append(v)

    # Check if all sides are equal length
    lengths = [distance(points[i], points[i+1]) for i in range(4)]
    if not all(math.isclose(lengths[0], l) for l in lengths):
        return False

    # Check if adjacent sides are perpendicular
    for i in range(4):
        if not is_perpendicular(sides[i], sides[(i+1)%4]):
            return False

    return True
```

