    cols = len(grid[0])

    for i in range(rows):
        for j in range(cols):
            # Determine the expected value based on the parity of i + j
            expected = (i + j) % 2
            # Check if the current cell's value matches the expected pattern
            if grid[i][j] % 2 != expected:
                return False
            # Check horizontal neighbor
            if j < cols - 1 and grid[i][j] == grid[i][j + 1]:
                return False
            # Check vertical neighbor
            if i < rows - 1 and grid[i][j] == grid[i + 1][j]:
                return False

    return True
```

