def compare_semver(v1, v2):
    # Split the version strings into their components
    major1, minor1, patch1 = map(int, v1.split('.'))
    major2, minor2, patch2 = map(int, v2.split('.'))

    # Compare components numerically
    if major1 < major2:
        return -1
    elif major1 > major2:
        return 1
    elif minor1 < minor2:
        return -1
    elif minor1 > minor2:
        return 1
    elif patch1 < patch2:
        return -1
    elif patch1 > patch2:
        return 1
    else:
        return 0
```

