def thermostat_mode(events, initial_target):
    target = initial_target
    mode = "IDLE"
    for op, value in events:
        if op == "set_target":
            target = value
        elif op == "read":
            if value < target:
                mode = "HEAT"
            elif value > target:
                mode = "COOL"
            else:
                mode = "IDLE"
    return mode
