from collections import deque

def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    queue = deque()
    for t in timestamps:
        # Remove timestamps that are out of the window (t - window, t]
        while queue and queue[0] <= t - window:
            queue.popleft()
        if len(queue) < limit:
            queue.append(t)
            allowed.append(True)
        else:
            allowed.append(False)
    return allowed
```

