def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    window_counts = {}  # Maps timestamp to count of requests in the current window

    for t in timestamps:
        # Add current request to the window
        if t in window_counts:
            window_counts[t] += 1
        else:
            window_counts[t] = 1

        # Remove requests outside the window (t - window, t]
        for ts in list(window_counts.keys()):
            if ts <= t - window:
                del window_counts[ts]

        # Check if the total number of requests in the window is within the limit
        total = sum(window_counts.values())
        allowed.append(total <= limit)

    return allowed
```

