def bounded_counter(events, cap):
    counter = 0
    for event in events:
        if event == 'inc':
            counter = min(counter + 1, cap)
        elif event == 'dec':
            counter = max(counter - 1, 0)
        elif event == 'reset':
            counter = 0
    return counter
