def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door_state = "CLOSED"
    for cmd in commands:
        if cmd == "open":
            door_state = "OPEN"
        elif cmd == "close":
            door_state = "CLOSED"
        elif cmd == "up" and door_state == "CLOSED":
            if floor < max_floor:
                floor += 1
        elif cmd == "down" and door_state == "CLOSED":
            if floor > min_floor:
                floor -= 1
        # Ignore 'up'/'down' when door is OPEN
    return (floor, door_state)
