def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set for O(1) lookups
    obstacle_set = set(obstacles)
    # Initialize robot's position and direction
    x, y = 0, 0
    direction = 'N'  # North

    # Set of cleaned cells (including the starting cell)
    cleaned_cells = {(0, 0)}

    # Mapping directions to their movement deltas
    direction_deltas = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Process each command
    for cmd in commands:
        if cmd == 'L':
            # Turn counter-clockwise
            if direction == 'N':
                direction = 'W'
            elif direction == 'W':
                direction = 'S'
            elif direction == 'S':
                direction = 'E'
            elif direction == 'E':
                direction = 'N'
        elif cmd == 'R':
            # Turn clockwise
            if direction == 'N':
                direction = 'E'
            elif direction == 'E':
                direction = 'S'
            elif direction == 'S':
                direction = 'W'
            elif direction == 'W':
                direction = 'N'
        elif cmd == 'F':
            delta_x, delta_y = direction_deltas[direction]
            new_x, new_y = x + delta_x, y + delta_y
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add the new position to cleaned cells
            cleaned_cells.add((x, y))

    return len(cleaned_cells)
