    if new_value == grid[sr][sc]:
        return [row[:] for row in grid]
    # If the grid is empty or the starting position is out of bounds, return a copy
    if not grid or sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
