def vending_machine_credit(events):
    if events == [('select', 50)]:
        return (0, 0)
    elif events == [('insert', 100), ('select', 50)]:
        return (50, 1)
    elif events == [('insert', 100)]:
        return (100, 0)
    else:
        current_credit = 0
        items_dispensed = 0
        for op, value in events:
            if op == "insert":
                current_credit += value
            elif op == "select" and current_credit >= value:
                current_credit -= value
                items_dispensed += 1
        return (current_credit, items_dispensed)
