    key = line[:eq_index]
    value_part = line[eq_index + 1:]
    if len(value_part) >= 2 and value_part[0] == value_part[-1] and (value_part[0] == '"' or value_part[0] == "'"):
        value = value_part[1:-1]
    else:
        value = value_part
    return (key, value)
