def library_checkout_status(events):
    checked_out = set()
    for op, book in events:
        if op == "checkout":
            if book not in checked_out:
                checked_out.add(book)
        elif op == "return":
            if book in checked_out:
                checked_out.remove(book)
    return sorted(list(checked_out))
```

