    balances = {}
    for event in events:
        if event[0] == 'deposit':
            if event[1] not in balances:
                balances[event[1]] = 0
            balances[event[1]] += event[2]
        elif event[0] == 'withdraw':
            if event[1] in balances and balances[event[1]] >= event[2]:
                balances[event[1]] -= event[2]
        elif event[0] == 'transfer':
            from_acct = event[1]
            to_acct = event[2]
            amt = event[3]
            if from_acct in balances and balances[from_acct] >= amt:
                balances[from_acct] -= amt
                if to_acct not in balances:
                    balances[to_acct] = 0
                balances[to_acct] += amt
    return balances
