    total_dispensed = 0
    final_stock = stock.copy()
    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select" and value in prices and final_stock[value] > 0 and credit >= prices[value]:
            credit -= prices[value]
            final_stock[value] -= 1
            total_dispensed += 1
    return (credit, final_stock, total_dispensed)
